  { id: "2", name: "Foundation", author: "Isaac Asimov", price: 24 },
  { id: "3", name: "The Left Hand of Darkness", author: "Ursula K. Le Guin", price: 18 },
  { id: "4", name: "Pride and Prejudice", author: "Jane Austen", price: 9.99 },
